/**
 * @description Save side of the guided setup: turns the screen's values into the record to save (only the editable
 * Integration Hub fields and Name; a new record is inactive) and a DML error into readable text with the field.
 * @group Integration Hub
 */
public with sharing class IntegrationHubSetupSave {

    private static final String ACTIVE_FIELD = 'Active__c';
    private static final Set<Schema.DisplayType> NUMBERS = new Set<Schema.DisplayType>{
        Schema.DisplayType.DOUBLE, Schema.DisplayType.INTEGER, Schema.DisplayType.CURRENCY, Schema.DisplayType.PERCENT,
        Schema.DisplayType.LONG
    };

    /**
     * @description Builds the record to save from the screen's values. Only the editable fields are accepted; a new
     * record is inactive.
     * @param objectName IH_Event__c or IH_Connection__c
     * @param input field values by API name, with Id to update
     * @return the record
     */
    public static SObject toRecord(String objectName, Map<String, Object> input) {
        Schema.DescribeSObjectResult d = IntegrationHubSetupSchema.describeOrNull(objectName);
        SObject rec = newRecord(d, toId(input.get('Id'), 'Id'));
        Map<String, Schema.SObjectField> all = d.fields.getMap();
        Set<String> allowed = allowedFields(objectName);
        for (String key : input.keySet()) {
            if (key != 'Id') {
                Schema.SObjectField f = allowed.contains(key.toLowerCase()) ? all.get(key) : null;
                if (f == null) {
                    throw IntegrationHubPreview.auraError('This field cannot be set here: ' + key);
                }
                rec.put(f, convert(f.getDescribe(), input.get(key)));
            }
        }
        if (rec.Id == null) {
            rec.put(ACTIVE_FIELD, false);
        }
        return rec;
    }

    /**
     * @description A save error in plain words, one line per error, with the field label and API name when Salesforce
     * names the field, e.g. "Path (Path__c): ...". Validation rule errors have no field and keep their message.
     * @param objectName the object saved
     * @param e the error
     * @return the text
     */
    public static String dmlMessage(String objectName, DmlException e) {
        Map<String, Schema.SObjectField> all = IntegrationHubSetupSchema.describeOrNull(objectName).fields.getMap();
        List<String> lines = new List<String>();
        for (Integer i = 0; i < e.getNumDml(); i++) {
            lines.add(lineOf(all, e.getDmlFieldNames(i), e.getDmlMessage(i)));
        }
        return lines.isEmpty() ? e.getMessage() : String.join(lines, '\n');
    }

    private static String lineOf(Map<String, Schema.SObjectField> all, List<String> fieldNames, String text) {
        if (fieldNames == null || fieldNames.isEmpty()) {
            return text;
        }
        Schema.SObjectField f = all.get(fieldNames[0]);
        String label = f == null ? fieldNames[0] : f.getDescribe().getLabel();
        return label + ' (' + fieldNames[0] + '): ' + text;
    }

    private static SObject newRecord(Schema.DescribeSObjectResult d, Id recordId) {
        if (recordId == null) {
            // The field defaults apply, as on the standard New page (Direction Outbound, Retention 90, ...).
            return d.getSObjectType().newSObject(null, true);
        }
        if (recordId.getSObjectType() != d.getSObjectType()) {
            throw IntegrationHubPreview.auraError('The record is not a ' + d.getLabel() + '.');
        }
        return d.getSObjectType().newSObject(recordId);
    }

    private static Set<String> allowedFields(String objectName) {
        Set<String> allowed = new Set<String>();
        for (String api : IntegrationHubSetupSchema.editableFields(objectName)) {
            allowed.add(api.toLowerCase());
        }
        return allowed;
    }

    private static Object convert(Schema.DescribeFieldResult d, Object value) {
        Schema.DisplayType t = d.getType();
        if (t == Schema.DisplayType.BOOLEAN) {
            return value instanceof Boolean ? (Boolean) value : 'true'.equalsIgnoreCase(String.valueOf(value));
        }
        String text = value == null ? '' : String.valueOf(value).trim();
        if (String.isBlank(text)) {
            return null;
        }
        if (NUMBERS.contains(t)) {
            return toNumber(text, d.getLabel());
        }
        return t == Schema.DisplayType.REFERENCE ? toId(text, d.getLabel()) : text;
    }

    private static Decimal toNumber(String text, String label) {
        try {
            return Decimal.valueOf(text);
        } catch (TypeException e) {
            throw IntegrationHubPreview.auraError(label + ': enter a number.');
        }
    }

    private static Id toId(Object value, String label) {
        String text = value == null ? '' : String.valueOf(value).trim();
        if (String.isBlank(text)) {
            return null;
        }
        try {
            return Id.valueOf(text);
        } catch (StringException e) {
            throw IntegrationHubPreview.auraError(label + ': not a record Id.');
        }
    }
}
